//! atty's shipped defaults.
//!
//! Every knob the user's `src/config.zig` can override has its
//! default value here. The resolver in `src/config_resolver.zig`
//! merges: each `pub const` the user declares wins; everything else
//! falls through to this file.
//!
//! Adding a new tunable upstream means adding it here and to the
//! resolver — user configs pick it up automatically, no merge
//! required. **Users do not edit this file**; edit `src/config.zig`.

const atty = @import("atty");

// ───── Modules ────────────────────────────────────────────────────────────
//
// The default tuple is dependency-free: history reads/writes your
// shell's own ~/.bash_history / ~/.zsh_history file — no `atuin`
// binary required, no daemon. Atty's `bin.atty.sh` prebuilt
// distribution runs out of the box.
//
// Want atuin? Override `modules` in your `src/config.zig` — see
// `src/config.def.zig` for the documented opt-in.

pub const modules = .{
    atty.modules.guardrail.configure(.{}),
    atty.modules.history.configure(.{}),
};

// ───── Proxy tunables ─────────────────────────────────────────────────────

/// poll() timeout — drives onTick cadence. Lower = more responsive
/// suggestion expiry; higher = lower idle CPU.
pub const tick_interval_ms: i32 = 100;

// ───── Visual style ───────────────────────────────────────────────────────

/// Ghost overlay style. Matches fish + zsh-autosuggestions: dim only.
pub const ghost_style: atty.Style = atty.style.presets.muted;

// ───── Key bindings ───────────────────────────────────────────────────────

/// Right-arrow / End / Ctrl+F accept the ghost suggestion; Alt+I
/// toggles incognito. Alt+letter is encoded classically (`ESC i`)
/// so it works on any terminal without protocol negotiation.
///
/// Ctrl+Shift+I would be a nicer mnemonic but classic terminal mode
/// collapses it to Tab. Binding it requires the kitty keyboard
/// protocol enabled *AND* a translator that converts the resulting
/// CSI-u sequences back to legacy bytes for the shell — otherwise
/// Ctrl+D, Ctrl+C and friends start arriving at the shell as
/// `\x1b[100;5u` etc and break it. Both are TODO.
pub const bindings: []const atty.keymap.Binding = &.{
    .{ .bytes = atty.keymap.key("Right"), .action = .ghost_accept },
    .{ .bytes = atty.keymap.key("End"), .action = .ghost_accept },
    .{ .bytes = atty.keymap.key("Ctrl+F"), .action = .ghost_accept },
    .{ .bytes = atty.keymap.key("Alt+i"), .action = .incognito_toggle },
};

/// Push the kitty keyboard protocol's `disambiguate` flag on startup
/// (and pop it on exit). **Off by default** because the disambiguated
/// sequences (e.g. `\x1b[100;5u` for Ctrl+D) reach the shell as
/// literal bytes — atty doesn't yet translate them back to the legacy
/// control codes the shell expects. Opt in only if you have a binding
/// (like `Ctrl+Shift+I`) that needs the disambiguated form and you're
/// OK with the shell-side breakage until the translator lands.
pub const enable_kitty_keyboard: bool = false;

// ───── Bottom status bar ──────────────────────────────────────────────────

/// Reserve rows at the bottom of the terminal for a status indicator
/// (via DECSTBM). Off by default — costs `statusbar_reserve_rows` of
/// vertical screen real estate. When enabled, modules can contribute
/// segments via the optional `statusText` hook (joined with ` │ `).
pub const statusbar_enabled: bool = false;

/// How many bottom rows to reserve. The last row holds the text;
/// rows above are blank visual padding from the shell's content.
pub const statusbar_reserve_rows: u16 = 2;

/// Visual style for the status bar text.
pub const statusbar_style: atty.Style = atty.style.presets.muted;

/// Base text shown when no module contributes anything. Empty means
/// the bar stays blank until a module sets something.
pub const statusbar_base_text: []const u8 = "";

/// Style for the 🔒 incognito segment in the status bar. Defaults to
/// muted red (dim + red) so it visually stands out against the rest
/// of the bar (which uses `statusbar_style`).
pub const incognito_status_style: atty.Style = .{ .dim = true, .fg = 1 };
